CREATE TABLE IF NOT EXISTS units_of_measure (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), code TEXT NOT NULL UNIQUE, name_ar TEXT NOT NULL, name_en TEXT NOT NULL, precision_digits SMALLINT NOT NULL DEFAULT 2 CHECK (precision_digits BETWEEN 0 AND 6), active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS warehouses (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), code TEXT NOT NULL UNIQUE, name_ar TEXT NOT NULL, name_en TEXT NOT NULL, warehouse_type TEXT NOT NULL CHECK (warehouse_type IN ('raw_material','finished_goods')), active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS parties (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), code TEXT NOT NULL UNIQUE, party_type TEXT NOT NULL CHECK (party_type IN ('customer','supplier','both')), name_ar TEXT NOT NULL, name_en TEXT, phone TEXT, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), code TEXT NOT NULL UNIQUE, name_ar TEXT NOT NULL, name_en TEXT, item_type TEXT NOT NULL CHECK (item_type IN ('raw_material','accessory','consumable','finished_good')), base_unit_id UUID NOT NULL REFERENCES units_of_measure(id), stock_tracked BOOLEAN NOT NULL DEFAULT TRUE, classification TEXT NOT NULL CHECK (classification IN ('materials','industrial_expense')), active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
